decoder.acyclic_projection:
def acyclic_projection(edge_probabilities, threshold=0.5):
    """Explicit greedy projection; never report it as the raw neural output."""
    prob = np.asarray(edge_probabilities, dtype=float)
    if prob.ndim != 2 or prob.shape[0] != prob.shape[1] or (not np.isfinite(prob).all()):
        raise ValueError('Invalid edge probabilities')
    n = len(prob)
    result = np.zeros((n, n), bool)
    rejected = []
    edges = sorted(((float(prob[i, j]), i, j) for i in range(n) for j in range(n) if i != j and prob[i, j] >= threshold), reverse=True)
    for score, i, j in edges:
        if result[j, i] or directed_path(result, j, i):
            rejected.append([i, j, score])
        else:
            result[i, j] = True
    topological_order(result)
    return (result, rejected)

decoder.dag_completion:
def dag_completion(partial):
    """One explicit acyclic completion, not an identification of ambiguous edges."""
    p = np.asarray(partial, dtype=bool)
    directed = p & ~p.T
    order = topological_order(directed)
    rank = {v: i for i, v in enumerate(order)}
    completed = directed.copy()
    chosen = []
    for i, j in combinations(range(len(p)), 2):
        if p[i, j] and p[j, i]:
            u, v = (i, j) if rank[i] < rank[j] else (j, i)
            completed[u, v] = True
            chosen.append([u, v])
    topological_order(completed)
    return (completed, chosen)

decoder.decode_graph:
def decode_graph(probabilities):
    p = np.asarray(probabilities)
    n = len(p)
    labels = p.argmax(-1)
    raw = np.zeros((n, n), bool)
    for i, j in combinations(range(n), 2):
        cls = int(labels[i, j])
        if cls == 1:
            raw[i, j] = True
        elif cls == 2:
            raw[j, i] = True
        elif cls == 3:
            raw[i, j] = raw[j, i] = True
    directed = raw & ~raw.T
    scores = np.where(directed, p[:, :, 1], 0)
    dag, rejected = acyclic_projection(scores, threshold=1e-12)
    partial = dag | raw & raw.T
    return (partial, {'removed_cycle_edges': rejected, 'raw_graph': raw.astype(int).tolist(), 'semantics': 'partially_directed_prediction_not_guaranteed_completed_PDAG'})

decoder.directed_path:
def directed_path(pdag, x, y):
    a = np.asarray(pdag, dtype=bool)
    directed = a & ~a.T
    seen = {x}
    stack = [x]
    while stack:
        u = stack.pop()
        for v in np.flatnonzero(directed[u]):
            if v == y:
                return True
            if int(v) not in seen:
                seen.add(int(v))
                stack.append(int(v))
    return False

decoder.topological_order:
def topological_order(graph):
    a = np.asarray(graph, dtype=bool)
    if a.ndim != 2 or a.shape[0] != a.shape[1] or np.diag(a).any():
        raise ValueError('Expected loop-free square directed graph')
    degree = a.sum(0).astype(int)
    todo = sorted(np.flatnonzero(degree == 0).tolist())
    result = []
    while todo:
        v = todo.pop(0)
        result.append(v)
        for child in np.flatnonzero(a[v]):
            degree[child] -= 1
            if degree[child] == 0:
                todo.append(int(child))
                todo.sort()
    if len(result) != len(a):
        raise ValueError('Directed cycle')
    return result
